//! Cross-language vector generated by pq.ts `signLeaf` (public-demo KNOWN secret).
use quantum_pq_vault::*;
fn k(v: &serde_json::Value, f: &str) -> Key { hex::decode(v[f].as_str().unwrap()).unwrap().try_into().unwrap() }

#[test]
fn ts_signed_vector_verifies_in_rust() {
    let v: serde_json::Value = serde_json::from_str(include_str!("vector-v1.json")).unwrap();
    assert_eq!(v["domain"].as_str().unwrap().as_bytes(), INTENT_DOMAIN);
    let it = Intent {
        program: k(&v, "program"), vault: k(&v, "vault"), mint: k(&v, "mint"), escrow: k(&v, "escrow"),
        destination: k(&v, "destination"), genesis: k(&v, "genesis"), amount: v["amount"].as_u64().unwrap(),
        nonce: v["nonce"].as_u64().unwrap(), expires_at: v["expires_at"].as_i64().unwrap(),
        leaf: v["leaf"].as_u64().unwrap() as u32, epoch: v["epoch"].as_u64().unwrap() as u32,
    };
    assert_eq!(it.genesis, DEVNET_GENESIS);
    assert_eq!(intent_message(&it), v["message"].as_str().unwrap());
    assert_eq!(hex::encode(intent_digest(&it)), v["digest"].as_str().unwrap());
    let proof = hex::decode(v["proof"].as_str().unwrap()).unwrap();
    let mut n = 0;
    let (leaf, root) = root_from_proof(&k(&v, "public_seed"), &intent_digest(&it), &proof, &mut n).unwrap();
    assert_eq!(leaf, 42);
    assert_eq!(hex::encode(root), v["root"].as_str().unwrap());
    // Full vault path with the TS proof, then one-bit tamper and amount change fail.
    let mut vault = Vault::create(it.program, it.vault, [2; 32], root, k(&v, "public_seed"), it.mint, it.escrow, it.destination, [6; 32], DEVNET_GENESIS, &DEVNET_GENESIS).unwrap();
    let f = ChainFacts { genesis: DEVNET_GENESIS, now: 10, escrow_owner: it.vault, escrow_mint: it.mint, escrow_amount: 500, destination_mint: it.mint, destination_owner: [6; 32] };
    let stage = |p: &[u8]| { let mut s = Session::open(false, [9; 32], &vault, sha256(p), 0, 600, 1).unwrap(); for (i, c) in p.chunks(MAX_CHUNK).enumerate() { s.append(&[9; 32], i, c, 1).unwrap(); } s };
    let mut bad = proof.clone(); bad[200] ^= 1;
    assert_eq!(stage(&bad).withdraw(&[9; 32], &mut vault.clone(), &it, &f, &mut n), Err(PqError::RootMismatch));
    assert_eq!(stage(&proof).withdraw(&[9; 32], &mut vault.clone(), &Intent { amount: 499, ..it }, &f, &mut n), Err(PqError::RootMismatch));
    assert!(stage(&proof).withdraw(&[9; 32], &mut vault, &it, &f, &mut n).is_ok());
}